Running command: cd /tmp; cat > /tmp/dump.c <<'EOF'
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "ucl.h"
static void dump(const ucl_object_t *o, int depth) {
    for (int i=0;i<depth;i++) printf("  ");
    if (o->type == UCL_OBJECT) {
        printf("OBJECT keylen=%zu key=%.*s\n", o->keylen, (int)o->keylen, o->key);
        const ucl_object_t *cur; ucl_object_iter_t it=NULL;
        while ((cur = ucl_object_iterate(o, &it, true))) dump(cur, depth+1);
    } else {
        printf("VAL keylen=%zu key=%.*s\n", o->keylen, (int)o->keylen, o->key);
    }
}
int main(int argc, char **argv) {
    FILE *f = fopen(argv[1], "rb");
    fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *data=malloc(sz); fread(data,1,sz,f); fclose(f);
    struct ucl_parser *parser = ucl_parser_new(0);
    ucl_parser_add_string(parser, data, sz);
    if (ucl_parser_get_error(parser)) { printf("ERR %s\n", ucl_parser_get_error(parser)); return 0; }
    dump(ucl_parser_get_object(parser), 0);
    ucl_parser_free(parser); free(data); return 0;
}
EOF
